use crate::terminal::{
    session::PtySessionConfig, PtyError, PtySession, PtySessionState, TerminalSignal,
};
use crate::worktree::WorktreeManager;
use parking_lot::{Mutex, RwLock};
use portable_pty::{native_pty_system, CommandBuilder, PtySize, PtySystem};
use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::mpsc;
use uuid::Uuid;

pub(crate) const LIFECYCLE_POLL_INTERVAL: Duration = Duration::from_millis(250);
const READER_SHUTDOWN_TIMEOUT: Duration = Duration::from_secs(2);

#[derive(Clone)]
pub struct PtyManager {
    sessions: Arc<RwLock<HashMap<String, Arc<PtySession>>>>,
    pty_system: Arc<Mutex<Box<dyn PtySystem + Send>>>,
}

impl Default for PtyManager {
    fn default() -> Self {
        Self::new()
    }
}

impl PtyManager {
    pub fn new() -> Self {
        Self {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            pty_system: Arc::new(Mutex::new(native_pty_system())),
        }
    }

    pub fn spawn(
        &self,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
    ) -> Result<(String, mpsc::Receiver<Vec<u8>>), PtyError> {
        let session_id = Uuid::new_v4().to_string();
        let rx = self.spawn_with_id_and_worktree(session_id.clone(), cmd, cols, rows, None)?;
        Ok((session_id, rx))
    }

    pub fn spawn_shell(
        &self,
        cols: u16,
        rows: u16,
    ) -> Result<(String, mpsc::Receiver<Vec<u8>>), PtyError> {
        let cmd = CommandBuilder::new_default_prog();
        self.spawn(cmd, cols, rows)
    }

    /// Spawn an interactive terminal owned by `worktree_path`.
    ///
    /// Interactive PTYs are deliberately multi-session.  The worktree writer lease is an
    /// exclusive mutation/agent guard and must not be used to serialize terminal panes:
    /// Orca-style split panes require two or more live PTYs in the same worktree.
    pub fn spawn_in_worktree(
        &self,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
        worktree_manager: &WorktreeManager,
        worktree_path: &Path,
    ) -> Result<(String, mpsc::Receiver<Vec<u8>>), PtyError> {
        let session_id = Uuid::new_v4().to_string();
        let canonical_worktree = worktree_manager
            .canonical_allowed_path(worktree_path)
            .map_err(|error| PtyError::Other(error.to_string()))?;
        let rx = self.spawn_with_id_and_worktree(
            session_id.clone(),
            cmd,
            cols,
            rows,
            Some(canonical_worktree),
        )?;
        Ok((session_id, rx))
    }

    pub fn spawn_with_id(
        &self,
        session_id: impl Into<String>,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
    ) -> Result<mpsc::Receiver<Vec<u8>>, PtyError> {
        self.spawn_with_id_and_worktree(session_id.into(), cmd, cols, rows, None)
    }

    fn spawn_with_id_and_worktree(
        &self,
        session_id: String,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
        worktree_path: Option<std::path::PathBuf>,
    ) -> Result<mpsc::Receiver<Vec<u8>>, PtyError> {
        if self.has_session(&session_id) {
            return Err(PtyError::Other(format!(
                "PTY session '{session_id}' already exists"
            )));
        }

        let pty_size = PtySize {
            rows,
            cols,
            pixel_width: 0,
            pixel_height: 0,
        };

        let pair = {
            let pty_system = self.pty_system.lock();
            pty_system
                .openpty(pty_size)
                .map_err(|e| PtyError::PtyCreationError(e.to_string()))?
        };

        let reader = pair
            .master
            .try_clone_reader()
            .map_err(|e| PtyError::IoError(format!("Failed to clone reader: {e}")))?;

        let writer = pair
            .master
            .take_writer()
            .map_err(|e| PtyError::IoError(format!("Failed to take writer: {e}")))?;

        let child = pair
            .slave
            .spawn_command(cmd)
            .map_err(|e| PtyError::SpawnError(format!("Failed to spawn command: {e}")))?;

        drop(pair.slave);

        let (tx, rx) = mpsc::channel::<Vec<u8>>(1024);
        let session = Arc::new(PtySession::new(PtySessionConfig {
            id: session_id.clone(),
            master: pair.master,
            child,
            writer,
            reader,
            cols,
            rows,
            tx,
            worktree_path,
        }));

        self.sessions
            .write()
            .insert(session_id.clone(), Arc::clone(&session));
        session.mark_running();
        self.start_lifecycle_watcher(session_id);
        Ok(rx)
    }

    fn start_lifecycle_watcher(&self, session_id: String) {
        let manager = self.clone();
        tokio::spawn(async move {
            let Some(session) = manager.get_session(&session_id) else {
                return;
            };
            let mut reader_task = session.take_reader_task();

            loop {
                let Some(session) = manager.get_session(&session_id) else {
                    break;
                };

                match session.state() {
                    PtySessionState::Exited { .. } | PtySessionState::Failed { .. } => {
                        session.close_output();
                        manager.remove_from_registry(&session_id);
                        break;
                    }
                    PtySessionState::Closing => {
                        tokio::time::sleep(LIFECYCLE_POLL_INTERVAL).await;
                        continue;
                    }
                    PtySessionState::Starting | PtySessionState::Running => {}
                }

                match session.poll_exit_code() {
                    Ok(Some(code)) => {
                        manager.finalize_natural_exit(&session_id, code).await;
                        break;
                    }
                    Ok(None)
                        if session.output_receiver_closed() || session.is_reader_finished() =>
                    {
                        if let Err(error) = manager.close_session(&session_id).await {
                            tracing::debug!(
                                "PTY receiver-drop cleanup failed for {}: {}",
                                session_id,
                                error
                            );
                        }
                        break;
                    }
                    Ok(None) => {}
                    Err(error) => {
                        session.mark_failed(error.to_string());
                        session.close_io();
                        session.close_output();
                        manager.remove_from_registry(&session_id);
                        break;
                    }
                }

                if let Some(ref mut handle) = reader_task {
                    tokio::select! {
                        _ = handle => {
                            reader_task = None;
                        }
                        _ = tokio::time::sleep(LIFECYCLE_POLL_INTERVAL) => {}
                    }
                } else {
                    tokio::time::sleep(LIFECYCLE_POLL_INTERVAL).await;
                }
            }
        });
    }

    async fn finalize_natural_exit(&self, session_id: &str, code: i32) {
        let Some(session) = self.get_session(session_id) else {
            return;
        };
        if !session.begin_closing() {
            return;
        }

        session.close_io();
        let _ = Self::join_reader_bounded(&session).await;
        session.mark_exited(Some(code));
        session.close_output();
        self.remove_from_registry(session_id);
    }

    async fn join_reader_bounded(session: &Arc<PtySession>) -> Result<(), PtyError> {
        let Some(mut reader_task) = session.take_reader_task() else {
            return Ok(());
        };

        match tokio::time::timeout(READER_SHUTDOWN_TIMEOUT, &mut reader_task).await {
            Ok(Ok(())) => Ok(()),
            Ok(Err(error)) => Err(PtyError::Other(format!("PTY reader task failed: {error}"))),
            Err(_) => {
                reader_task.abort();
                Err(PtyError::Other(
                    "Timed out waiting for PTY reader shutdown".into(),
                ))
            }
        }
    }

    pub async fn close_session(&self, session_id: &str) -> Result<(), PtyError> {
        let Some(session) = self.get_session(session_id) else {
            return Ok(());
        };

        if !session.begin_closing() {
            if matches!(
                session.state(),
                PtySessionState::Exited { .. } | PtySessionState::Failed { .. }
            ) {
                session.close_output();
                self.remove_from_registry(session_id);
                return Ok(());
            }

            let deadline = tokio::time::Instant::now() + READER_SHUTDOWN_TIMEOUT;
            while tokio::time::Instant::now() < deadline {
                if !self.has_session(session_id) {
                    return Ok(());
                }
                tokio::time::sleep(LIFECYCLE_POLL_INTERVAL).await;
            }
            return Err(PtyError::Other(format!(
                "Timed out waiting for concurrent close of session '{session_id}'"
            )));
        }

        let mut first_error: Option<PtyError> = None;
        let mut exit_code = match session.poll_exit_code() {
            Ok(code) => code,
            Err(error) => {
                first_error = Some(error);
                None
            }
        };

        if exit_code.is_none() {
            if let Err(signal_error) = session.signal(TerminalSignal::Terminate) {
                if let Err(kill_error) = session.kill() {
                    first_error = Some(PtyError::KillError(format!(
                        "{signal_error}; fallback kill failed: {kill_error}"
                    )));
                }
            }
        }

        session.close_io();

        if let Err(reader_error) = Self::join_reader_bounded(&session).await {
            let _ = session
                .signal(TerminalSignal::Kill)
                .or_else(|_| session.kill());
            if first_error.is_none() {
                first_error = Some(reader_error);
            }
        }

        if exit_code.is_none() && !session.is_reaped() {
            let session_for_wait = Arc::clone(&session);
            match tokio::task::spawn_blocking(move || session_for_wait.wait_and_reap()).await {
                Ok(Ok(code)) => exit_code = code,
                Ok(Err(error)) => {
                    if first_error.is_none() {
                        first_error = Some(error);
                    }
                }
                Err(error) => {
                    if first_error.is_none() {
                        first_error = Some(PtyError::Other(format!(
                            "PTY child reap task failed: {error}"
                        )));
                    }
                }
            }
        }

        if let Some(error) = first_error {
            session.mark_failed(error.to_string());
            session.close_output();
            self.remove_from_registry(session_id);
            return Err(error);
        }

        session.mark_exited(exit_code);
        session.close_output();
        self.remove_from_registry(session_id);
        Ok(())
    }

    pub fn write_input(&self, session_id: &str, data: &[u8]) -> Result<(), PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        session.write_input(data)
    }

    pub fn resize(&self, session_id: &str, cols: u16, rows: u16) -> Result<(), PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        session.resize(cols, rows)
    }

    pub fn kill(&self, session_id: &str) -> Result<(), PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        session.kill()
    }

    pub fn signal(&self, session_id: &str, signal: TerminalSignal) -> Result<(), PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        session.signal(signal)
    }

    pub fn get_session(&self, session_id: &str) -> Option<Arc<PtySession>> {
        self.sessions.read().get(session_id).cloned()
    }

    pub fn has_session(&self, session_id: &str) -> bool {
        self.sessions.read().contains_key(session_id)
    }

    fn remove_from_registry(&self, session_id: &str) -> Option<Arc<PtySession>> {
        self.sessions.write().remove(session_id)
    }

    pub fn list_sessions(&self) -> Vec<String> {
        self.sessions.read().keys().cloned().collect()
    }

    pub fn session_count(&self) -> usize {
        self.sessions.read().len()
    }

    pub fn is_alive(&self, session_id: &str) -> Result<bool, PtyError> {
        let session = self
            .get_session(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))?;
        Ok(session.is_alive())
    }
}

use crate::terminal::PtyError;
use parking_lot::Mutex;
use portable_pty::{Child, MasterPty, PtySize};
use std::io::{Read, Write};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use tokio::sync::mpsc;
use tokio::task::JoinHandle;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PtySessionState {
    Starting,
    Running,
    Closing,
    Exited { code: Option<i32> },
    Failed { reason: String },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum TerminalSignal {
    Interrupt,
    Terminate,
    Kill,
}

pub(crate) struct PtySessionConfig {
    pub id: String,
    pub master: Box<dyn MasterPty + Send>,
    pub child: Box<dyn Child + Send + Sync>,
    pub writer: Box<dyn Write + Send>,
    pub reader: Box<dyn Read + Send>,
    pub cols: u16,
    pub rows: u16,
    pub tx: mpsc::Sender<Vec<u8>>,
    /// Canonical worktree/repository root that owns this interactive terminal.
    ///
    /// Interactive terminals are intentionally *not* exclusive worktree writers: Orca
    /// allows several PTYs in the same worktree.  Keeping the ownership path directly on
    /// the PTY session preserves session listing and CWD validation without abusing the
    /// exclusive writer lease used by agent/destructive-operation safety.
    pub worktree_path: Option<PathBuf>,
}

pub struct PtySession {
    pub id: String,
    master: Arc<Mutex<Option<Box<dyn MasterPty + Send>>>>,
    writer: Arc<Mutex<Option<Box<dyn Write + Send>>>>,
    child: Arc<Mutex<Option<Box<dyn Child + Send + Sync>>>>,
    reader_task: Arc<Mutex<Option<JoinHandle<()>>>>,
    output_tx: Arc<Mutex<Option<mpsc::Sender<Vec<u8>>>>>,
    worktree_path: Option<PathBuf>,
    reader_finished: Arc<AtomicBool>,
    reaped: Arc<AtomicBool>,
    state: Arc<Mutex<PtySessionState>>,
    cols: Arc<Mutex<u16>>,
    rows: Arc<Mutex<u16>>,
}

impl PtySession {
    pub(crate) fn new(config: PtySessionConfig) -> Self {
        let output_tx = Arc::new(Mutex::new(Some(config.tx)));
        let reader_tx = output_tx
            .lock()
            .as_ref()
            .expect("output sender must exist while starting reader")
            .clone();
        let reader = config.reader;
        let reader_finished = Arc::new(AtomicBool::new(false));
        let reader_finished_task = Arc::clone(&reader_finished);
        let reader_task = tokio::task::spawn_blocking(move || {
            let mut reader = reader;
            let mut buf = [0u8; 4096];
            loop {
                match reader.read(&mut buf) {
                    Ok(0) => break,
                    Ok(n) => {
                        if reader_tx.blocking_send(buf[..n].to_vec()).is_err() {
                            break;
                        }
                    }
                    Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                    Err(_) => break,
                }
            }
            reader_finished_task.store(true, Ordering::Release);
        });

        Self {
            id: config.id,
            master: Arc::new(Mutex::new(Some(config.master))),
            writer: Arc::new(Mutex::new(Some(config.writer))),
            child: Arc::new(Mutex::new(Some(config.child))),
            reader_task: Arc::new(Mutex::new(Some(reader_task))),
            output_tx,
            worktree_path: config.worktree_path,
            reader_finished,
            reaped: Arc::new(AtomicBool::new(false)),
            state: Arc::new(Mutex::new(PtySessionState::Starting)),
            cols: Arc::new(Mutex::new(config.cols)),
            rows: Arc::new(Mutex::new(config.rows)),
        }
    }

    pub fn id(&self) -> &str {
        &self.id
    }

    pub fn state(&self) -> PtySessionState {
        self.state.lock().clone()
    }

    pub(crate) fn mark_running(&self) {
        let mut state = self.state.lock();
        if matches!(*state, PtySessionState::Starting) {
            *state = PtySessionState::Running;
        }
    }

    pub(crate) fn begin_closing(&self) -> bool {
        let mut state = self.state.lock();
        match *state {
            PtySessionState::Starting | PtySessionState::Running => {
                *state = PtySessionState::Closing;
                true
            }
            PtySessionState::Closing
            | PtySessionState::Exited { .. }
            | PtySessionState::Failed { .. } => false,
        }
    }

    pub(crate) fn mark_exited(&self, code: Option<i32>) {
        *self.state.lock() = PtySessionState::Exited { code };
    }

    pub(crate) fn mark_failed(&self, reason: impl Into<String>) {
        *self.state.lock() = PtySessionState::Failed {
            reason: reason.into(),
        };
    }

    pub fn pid(&self) -> Option<u32> {
        self.child
            .lock()
            .as_ref()
            .and_then(|child| child.process_id())
    }

    pub fn worktree_path(&self) -> Option<PathBuf> {
        self.worktree_path.clone()
    }

    pub fn write_input(&self, data: &[u8]) -> Result<(), PtyError> {
        let mut writer = self.writer.lock();
        let writer = writer
            .as_mut()
            .ok_or_else(|| PtyError::IoError("PTY writer is closed".into()))?;
        writer
            .write_all(data)
            .map_err(|e| PtyError::IoError(format!("Write failed: {e}")))?;
        writer
            .flush()
            .map_err(|e| PtyError::IoError(format!("Flush failed: {e}")))?;
        Ok(())
    }

    pub fn resize(&self, cols: u16, rows: u16) -> Result<(), PtyError> {
        let size = PtySize {
            rows,
            cols,
            pixel_width: 0,
            pixel_height: 0,
        };
        let master = self.master.lock();
        let master = master
            .as_ref()
            .ok_or_else(|| PtyError::ResizeError("PTY master is closed".into()))?;
        master
            .resize(size)
            .map_err(|e| PtyError::ResizeError(format!("Resize failed: {e}")))?;
        *self.cols.lock() = cols;
        *self.rows.lock() = rows;
        Ok(())
    }

    pub fn get_size(&self) -> (u16, u16) {
        (*self.cols.lock(), *self.rows.lock())
    }

    pub fn kill(&self) -> Result<(), PtyError> {
        let mut child = self.child.lock();
        let Some(child) = child.as_mut() else {
            return Ok(());
        };
        child
            .kill()
            .map_err(|e| PtyError::KillError(format!("Kill failed: {e}")))
    }

    #[cfg(unix)]
    pub fn signal(&self, signal: TerminalSignal) -> Result<(), PtyError> {
        if signal == TerminalSignal::Interrupt {
            // A literal VINTR byte goes through the PTY line discipline, which directs
            // SIGINT to the terminal's current foreground process group.
            return self.write_input(&[0x03]);
        }

        let pid = self
            .pid()
            .ok_or_else(|| PtyError::KillError("PID not available for signal".into()))?;
        let sig = match signal {
            TerminalSignal::Interrupt => libc::SIGINT,
            TerminalSignal::Terminate => libc::SIGTERM,
            TerminalSignal::Kill => libc::SIGKILL,
        };

        // portable-pty creates the child as the PTY session/process-group leader on Unix.
        // Addressing the negative pid signals the whole job-control process group rather
        // than only the shell process.
        let result = unsafe { libc::kill(-(pid as i32), sig) };
        if result == 0 {
            return Ok(());
        }

        Err(PtyError::KillError(format!(
            "Failed to send signal {signal:?} to process group {pid}: {}",
            std::io::Error::last_os_error()
        )))
    }

    #[cfg(not(unix))]
    pub fn signal(&self, signal: TerminalSignal) -> Result<(), PtyError> {
        match signal {
            TerminalSignal::Interrupt | TerminalSignal::Terminate | TerminalSignal::Kill => {
                self.kill()
            }
        }
    }

    pub(crate) fn poll_exit_code(&self) -> Result<Option<i32>, PtyError> {
        let mut child_slot = self.child.lock();
        let Some(child) = child_slot.as_mut() else {
            return Ok(match self.state() {
                PtySessionState::Exited { code } => code,
                _ => None,
            });
        };

        let status = child
            .try_wait()
            .map_err(|e| PtyError::Other(format!("try_wait failed: {e}")))?;
        let Some(status) = status else {
            return Ok(None);
        };

        let code = status.exit_code() as i32;
        child_slot.take();
        self.reaped.store(true, Ordering::Release);
        Ok(Some(code))
    }

    pub(crate) fn wait_and_reap(&self) -> Result<Option<i32>, PtyError> {
        let mut child_slot = self.child.lock();
        let Some(mut child) = child_slot.take() else {
            return Ok(match self.state() {
                PtySessionState::Exited { code } => code,
                _ => None,
            });
        };

        let result = child
            .wait()
            .map(|status| Some(status.exit_code() as i32))
            .map_err(|e| PtyError::Other(format!("wait failed: {e}")));
        self.reaped.store(true, Ordering::Release);
        result
    }

    pub fn is_alive(&self) -> bool {
        matches!(self.poll_exit_code(), Ok(None)) && !self.is_reaped()
    }

    pub fn is_reaped(&self) -> bool {
        self.reaped.load(Ordering::Acquire)
    }

    pub fn is_reader_finished(&self) -> bool {
        self.reader_finished.load(Ordering::Acquire)
    }

    pub(crate) fn output_receiver_closed(&self) -> bool {
        self.output_tx
            .lock()
            .as_ref()
            .map(mpsc::Sender::is_closed)
            .unwrap_or(true)
    }

    pub(crate) fn close_output(&self) {
        self.output_tx.lock().take();
    }

    pub(crate) fn close_io(&self) {
        self.writer.lock().take();
        self.master.lock().take();
    }

    pub(crate) fn take_reader_task(&self) -> Option<JoinHandle<()>> {
        self.reader_task.lock().take()
    }
}

impl Drop for PtySession {
    fn drop(&mut self) {
        self.writer.lock().take();
        self.master.lock().take();
        self.output_tx.lock().take();
        if let Some(handle) = self.reader_task.lock().take() {
            handle.abort();
        }
    }
}

use parking_lot::RwLock;
use std::collections::{HashMap, VecDeque};
use std::sync::Arc;
use tokio::sync::broadcast;

const DEFAULT_BUFFER_CAPACITY: usize = 512 * 1024; // 512 KiB
const BROADCAST_CAPACITY: usize = 1024;

pub struct BoundedBuffer {
    capacity: usize,
    chunks: VecDeque<Vec<u8>>,
    current_size: usize,
}

impl BoundedBuffer {
    pub fn new(capacity: usize) -> Self {
        Self {
            capacity,
            chunks: VecDeque::new(),
            current_size: 0,
        }
    }

    pub fn push(&mut self, chunk: Vec<u8>) {
        if chunk.is_empty() {
            return;
        }
        self.current_size += chunk.len();
        self.chunks.push_back(chunk);

        while self.current_size > self.capacity && !self.chunks.is_empty() {
            if let Some(front) = self.chunks.pop_front() {
                self.current_size -= front.len();
            }
        }
    }

    pub fn snapshot(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(self.current_size);
        for chunk in &self.chunks {
            out.extend_from_slice(chunk);
        }
        out
    }
}

struct SessionHub {
    buffer: BoundedBuffer,
    sender: broadcast::Sender<Vec<u8>>,
}

#[derive(Clone)]
pub struct TerminalOutputHub {
    sessions: Arc<RwLock<HashMap<String, Arc<RwLock<SessionHub>>>>>,
    capacity: usize,
}

impl Default for TerminalOutputHub {
    fn default() -> Self {
        Self::new(DEFAULT_BUFFER_CAPACITY)
    }
}

impl TerminalOutputHub {
    pub fn new(capacity: usize) -> Self {
        Self {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            capacity,
        }
    }

    pub fn register_session(&self, session_id: &str) -> broadcast::Receiver<Vec<u8>> {
        let (tx, rx) = broadcast::channel(BROADCAST_CAPACITY);
        let hub = SessionHub {
            buffer: BoundedBuffer::new(self.capacity),
            sender: tx,
        };
        self.sessions
            .write()
            .insert(session_id.to_string(), Arc::new(RwLock::new(hub)));
        rx
    }

    pub fn publish(&self, session_id: &str, chunk: Vec<u8>) {
        let session_hub = {
            let sessions = self.sessions.read();
            sessions.get(session_id).cloned()
        };

        if let Some(hub) = session_hub {
            let mut hub = hub.write();
            hub.buffer.push(chunk.clone());
            // It is okay if there are no active receivers; send returns Err in that case
            let _ = hub.sender.send(chunk);
        }
    }

    pub fn subscribe(&self, session_id: &str) -> Option<(Vec<u8>, broadcast::Receiver<Vec<u8>>)> {
        let session_hub = {
            let sessions = self.sessions.read();
            sessions.get(session_id).cloned()
        }?;

        let hub = session_hub.read();
        let history = hub.buffer.snapshot();
        let rx = hub.sender.subscribe();
        Some((history, rx))
    }

    pub fn remove_session(&self, session_id: &str) {
        self.sessions.write().remove(session_id);
    }

    pub fn has_session(&self, session_id: &str) -> bool {
        self.sessions.read().contains_key(session_id)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_output_hub_replay_and_broadcast() {
        let hub = TerminalOutputHub::new(1024);
        let session_id = "test-session";
        let _initial_rx = hub.register_session(session_id);

        hub.publish(session_id, b"hello ".to_vec());
        hub.publish(session_id, b"world\n".to_vec());

        let (history, mut rx) = hub.subscribe(session_id).expect("session exists");
        assert_eq!(history, b"hello world\n");

        hub.publish(session_id, b"live chunk".to_vec());
        let received = rx.recv().await.expect("received live message");
        assert_eq!(received, b"live chunk");
    }

    #[tokio::test]
    async fn test_bounded_buffer_overflow() {
        let mut buffer = BoundedBuffer::new(10);
        buffer.push(b"12345".to_vec());
        buffer.push(b"67890".to_vec());
        buffer.push(b"abcdef".to_vec());

        let snap = buffer.snapshot();
        assert!(snap.len() <= 16); // pops chunks until under capacity
        assert!(snap.ends_with(b"abcdef"));
    }
}

use crate::terminal::output_hub::TerminalOutputHub;
use crate::terminal::{PtyError, PtyManager, PtySession, TerminalSignal};
use crate::worktree::manager::WorktreeManager;
use portable_pty::CommandBuilder;
use std::path::Path;
use std::sync::Arc;
use tokio::sync::broadcast;

#[derive(Clone)]
pub struct TerminalService {
    pty_manager: Arc<PtyManager>,
    output_hub: Arc<TerminalOutputHub>,
}

impl Default for TerminalService {
    fn default() -> Self {
        Self::new(
            Arc::new(PtyManager::new()),
            Arc::new(TerminalOutputHub::default()),
        )
    }
}

impl TerminalService {
    pub fn new(pty_manager: Arc<PtyManager>, output_hub: Arc<TerminalOutputHub>) -> Self {
        Self {
            pty_manager,
            output_hub,
        }
    }

    pub fn pty_manager(&self) -> &Arc<PtyManager> {
        &self.pty_manager
    }

    pub fn output_hub(&self) -> &Arc<TerminalOutputHub> {
        &self.output_hub
    }

    pub fn spawn_in_worktree(
        &self,
        cmd: CommandBuilder,
        cols: u16,
        rows: u16,
        worktree_manager: &WorktreeManager,
        worktree_path: &Path,
    ) -> Result<(String, broadcast::Receiver<Vec<u8>>), PtyError> {
        let (session_id, mut pty_rx) =
            self.pty_manager
                .spawn_in_worktree(cmd, cols, rows, worktree_manager, worktree_path)?;

        let broadcast_rx = self.output_hub.register_session(&session_id);

        // Spawn output pump task from PTY reader to OutputHub
        let output_hub = Arc::clone(&self.output_hub);
        let session_id_clone = session_id.clone();
        tokio::spawn(async move {
            while let Some(chunk) = pty_rx.recv().await {
                output_hub.publish(&session_id_clone, chunk);
            }
        });

        Ok((session_id, broadcast_rx))
    }

    pub fn attach(
        &self,
        session_id: &str,
    ) -> Result<(Vec<u8>, broadcast::Receiver<Vec<u8>>), PtyError> {
        if !self
            .pty_manager
            .list_sessions()
            .contains(&session_id.to_string())
        {
            return Err(PtyError::SessionNotFound(session_id.to_string()));
        }

        self.output_hub
            .subscribe(session_id)
            .ok_or_else(|| PtyError::SessionNotFound(session_id.to_string()))
    }

    pub fn write_input(&self, session_id: &str, data: &[u8]) -> Result<(), PtyError> {
        self.pty_manager.write_input(session_id, data)
    }

    pub fn resize(&self, session_id: &str, cols: u16, rows: u16) -> Result<(), PtyError> {
        self.pty_manager.resize(session_id, cols, rows)
    }

    pub fn signal(&self, session_id: &str, signal: TerminalSignal) -> Result<(), PtyError> {
        self.pty_manager.signal(session_id, signal)
    }

    pub async fn close_session(&self, session_id: &str) -> Result<(), PtyError> {
        self.output_hub.remove_session(session_id);
        self.pty_manager.close_session(session_id).await
    }

    pub fn list_sessions(&self) -> Vec<String> {
        self.pty_manager.list_sessions()
    }

    pub fn get_session(&self, session_id: &str) -> Option<Arc<PtySession>> {
        self.pty_manager.get_session(session_id)
    }
}

