pub fn create_remote_router(state: Arc<RemoteGatewayState>) -> Router {
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    Router::new()
        .route("/api/v1/health", get(health_check))
        .route("/api/v1/pair/exchange", post(pair_exchange))
        .route("/api/v1/sessions", get(list_sessions))
        .route("/api/v1/workspace/state", get(get_workspace_state))
        .route(
            "/api/v1/terminal/preferences",
            get(get_terminal_preferences),
        )
        .route(
            "/api/v1/workspace/worktrees",
            post(create_worktree).delete(delete_worktree),
        )
        .route("/api/v1/devices", get(list_devices))
        .route("/api/v1/devices/{id}/revoke", post(revoke_device))
        .route("/api/v1/events", get(ws_events_handler))
        .route("/api/v1/terminal/{sessionId}", get(ws_terminal_handler))
        .fallback(get(serve_static_or_index))
        .layer(cors)
        .with_state(state)
}

pub struct RemoteServerHandle {
    shutdown_tx: tokio::sync::oneshot::Sender<()>,
}

impl RemoteServerHandle {
    pub fn stop(self) {
        let _ = self.shutdown_tx.send(());
    }
}

pub async fn start_remote_server(
    state: Arc<RemoteGatewayState>,
) -> Result<(RemoteServerHandle, SocketAddr), String> {
    let config = state.config.read().clone();
    let bind_host = match config.mode {
        RemoteNetworkMode::Off => return Err("Remote gateway is OFF".into()),
        _ => "0.0.0.0",
    };

    let bind_addr: SocketAddr = format!("{bind_host}:{}", config.port)
        .parse()
        .map_err(|e| format!("Invalid bind address: {e}"))?;

    let listener = tokio::net::TcpListener::bind(bind_addr)
        .await
        .map_err(|e| format!("Failed to bind to {bind_addr}: {e}"))?;

    let local_addr = listener
        .local_addr()
        .map_err(|e| format!("Failed to get local address: {e}"))?;

    let router = create_remote_router(Arc::clone(&state));
    let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel::<()>();

    *state.is_running.write() = true;
    *state.bound_address.write() = Some(local_addr.to_string());

    let state_clone = Arc::clone(&state);
    tokio::spawn(async move {
        axum::serve(listener, router)
            .with_graceful_shutdown(async move {
                let _ = shutdown_rx.await;
            })
            .await
            .ok();

        *state_clone.is_running.write() = false;
        *state_clone.bound_address.write() = None;
    });

    Ok((RemoteServerHandle { shutdown_tx }, local_addr))
}

use serde::{Deserialize, Serialize};
use std::process::Command;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TailscaleStatus {
    pub installed: bool,
    pub running: bool,
    pub tailnet_name: Option<String>,
    pub self_dns: Option<String>,
    pub serve_active: bool,
}

pub trait CommandRunner: Send + Sync {
    fn run(&self, program: &str, args: &[&str]) -> Result<String, String>;
}

pub struct SystemCommandRunner;

impl CommandRunner for SystemCommandRunner {
    fn run(&self, program: &str, args: &[&str]) -> Result<String, String> {
        let output = Command::new(program)
            .args(args)
            .output()
            .map_err(|e| e.to_string())?;

        if output.status.success() {
            String::from_utf8(output.stdout).map_err(|e| e.to_string())
        } else {
            Err(String::from_utf8_lossy(&output.stderr).to_string())
        }
    }
}

pub fn check_tailscale_status(runner: &dyn CommandRunner) -> TailscaleStatus {
    let status_res = runner.run("tailscale", &["status", "--json"]);
    let Ok(json_str) = status_res else {
        return TailscaleStatus {
            installed: false,
            running: false,
            tailnet_name: None,
            self_dns: None,
            serve_active: false,
        };
    };

    let Ok(val) = serde_json::from_str::<serde_json::Value>(&json_str) else {
        return TailscaleStatus {
            installed: true,
            running: false,
            tailnet_name: None,
            self_dns: None,
            serve_active: false,
        };
    };

    let running = val.get("BackendState").and_then(|v| v.as_str()) == Some("Running");
    let self_dns = val
        .get("Self")
        .and_then(|s| s.get("DNSName"))
        .and_then(|d| d.as_str())
        .map(|s| s.trim_end_matches('.').to_string());
    let tailnet_name = val
        .get("CurrentTailnet")
        .and_then(|t| t.get("Name"))
        .and_then(|n| n.as_str())
        .map(|s| s.to_string());

    let serve_res = runner.run("tailscale", &["serve", "status", "--json"]);
    let serve_active = serve_res.is_ok() && !serve_res.unwrap().trim().is_empty();

    TailscaleStatus {
        installed: true,
        running,
        tailnet_name,
        self_dns,
        serve_active,
    }
}

//! Native notification domain.
//!
//! Rust decides *how* to talk to the OS safely; the frontend decides *whether*
//! an application event should notify. React state, active-tab knowledge, and
//! user-event dedupe deliberately stay out of this module.

pub mod audio;
pub mod model;
pub mod permission;
pub mod service;

pub use audio::*;
