// ---------------------------------------------------------------------------
// Content policy
// ---------------------------------------------------------------------------

/// Strip control characters and collapse pathological whitespace.
///
/// Terminal titles and agent labels are attacker-adjacent input: they can
/// carry escape sequences, newlines, or padding designed to spoof notification
/// text. Everything below `0x20` plus DEL and the Unicode line separators is
/// replaced by a space, then runs of whitespace collapse to one space.
pub fn sanitize_text(raw: &str) -> String {
    let mut out = String::with_capacity(raw.len());
    let mut pending_space = false;

    for ch in raw.chars() {
        let is_blank = ch.is_control()
            || ch.is_whitespace()
            || matches!(ch, '\u{2028}' | '\u{2029}' | '\u{feff}');

        if is_blank {
            pending_space = !out.is_empty();
            continue;
        }

        if pending_space {
            out.push(' ');
            pending_space = false;
        }
        out.push(ch);
    }

    out
}

/// Truncate on a character boundary, appending an ellipsis when shortened.
pub fn truncate_text(text: &str, max_len: usize) -> String {
    if text.chars().count() <= max_len {
        return text.to_string();
    }
    if max_len == 0 {
        return String::new();
    }

    // Reserve one character for the ellipsis.
    let keep = max_len.saturating_sub(1);
    let mut out: String = text.chars().take(keep).collect();
    while out.ends_with(' ') {
        out.pop();
    }
    out.push('\u{2026}');
    out
}

fn clean_field(value: Option<&str>) -> Option<String> {
    let cleaned = sanitize_text(value?);
    if cleaned.is_empty() {
        None
    } else {
        Some(cleaned)
    }
}

/// Render final notification text for a dispatch request.
///
/// Deliberately conservative: no shell output, no agent prompt text, and no
/// absolute paths. Native notifications can appear on a lock screen, so only
/// short display labels the user already chose are included.
pub fn format_notification(request: &DispatchNotificationRequest) -> NotificationContent {
    let agent = clean_field(request.agent_label.as_deref());
    let worktree = clean_field(request.worktree_label.as_deref());
    let workspace = clean_field(request.workspace_label.as_deref());
    let terminal = clean_field(request.terminal_title.as_deref());

    let (title, body) = match request.source {
        NotificationSource::AgentTaskComplete => {
            let title = match agent {
                Some(agent) => format!("{agent} finished"),
                None => "Agent finished".to_string(),
            };
            let body = worktree
                .or(workspace)
                .unwrap_or_else(|| "Task complete".to_string());
            (title, body)
        }
        NotificationSource::TerminalBell => {
            let title = "Terminal needs attention".to_string();
            let location = worktree.or(workspace);
            let body = match (location, terminal) {
                (Some(location), Some(terminal)) => format!("{location} \u{b7} {terminal}"),
                (Some(location), None) => location,
                (None, Some(terminal)) => terminal,
                (None, None) => "A terminal rang the bell".to_string(),
            };
            (title, body)
        }
        NotificationSource::Test => (
            "Ferryx notifications are working".to_string(),
            "Test notification".to_string(),
        ),
    };

    NotificationContent {
        title: truncate_text(&title, MAX_TITLE_LEN),
        body: truncate_text(&body, MAX_BODY_LEN),
    }
}

// ---------------------------------------------------------------------------
// Audio validation
// ---------------------------------------------------------------------------

/// Convert a frontend volume percentage to a linear gain.
///
/// Accepts `0..=100`; anything outside (including NaN) clamps into range so a
/// malformed setting can never produce a deafening or negative gain.
pub fn normalize_volume(percent: f32) -> f32 {
    if percent.is_nan() {
        return 0.0;
    }
    (percent / 100.0).clamp(0.0, 1.0)
}

/// True when the extension matches an enabled decoder.
pub fn is_supported_audio_extension(path: &Path) -> bool {
    path.extension()
        .and_then(|ext| ext.to_str())
        .map(|ext| {
            let lower = ext.to_ascii_lowercase();
            SUPPORTED_AUDIO_EXTENSIONS.contains(&lower.as_str())
        })
        .unwrap_or(false)
}

/// Validate a custom sound path before any decoding is attempted.
///
/// Returns the canonicalized path so playback never follows a path that
/// changed between validation and open.
pub fn validate_audio_path(path: &Path) -> Result<PathBuf, PlaySoundReason> {
    if !is_supported_audio_extension(path) {
        return Err(PlaySoundReason::UnsupportedFormat);
    }

    let canonical = path.canonicalize().map_err(|_| PlaySoundReason::NotFound)?;

    let metadata = canonical
        .metadata()
        .map_err(|_| PlaySoundReason::NotFound)?;

    if !metadata.is_file() {
        return Err(PlaySoundReason::NotFound);
    }
    if metadata.len() > MAX_AUDIO_FILE_BYTES {
        return Err(PlaySoundReason::FileTooLarge);
    }

    Ok(canonical)
}

/// Display name for a picked file, falling back to the full path string.
pub fn audio_display_name(path: &Path) -> String {
    path.file_name()
        .and_then(|name| name.to_str())
        .map(|name| name.to_string())
        .unwrap_or_else(|| path.to_string_lossy().to_string())
}

//! Authoritative notification permission queries.

use super::model::{
    NotificationAuthorization, NotificationPermissionRequestDto, NotificationPermissionStatusDto,
    NotificationPlatform,
};

/// Seam over the OS permission backend.
pub trait NotificationPermissionProvider: Send + Sync {
    fn status(&self) -> NotificationPermissionStatusDto;
    fn request(&self) -> NotificationPermissionRequestDto;
}

/// Provider selected for the current build target.
pub fn platform_permission_provider() -> Box<dyn NotificationPermissionProvider> {
    #[cfg(target_os = "macos")]
    {
        Box::new(macos::MacosPermissionProvider)
    }
    #[cfg(not(target_os = "macos"))]
    {
        Box::new(DesktopFallbackPermissionProvider)
    }
}

/// Non-authoritative provider for platforms without a real permission query.
#[derive(Debug, Default, Clone, Copy)]
pub struct DesktopFallbackPermissionProvider;

impl NotificationPermissionProvider for DesktopFallbackPermissionProvider {
    fn status(&self) -> NotificationPermissionStatusDto {
        let platform = NotificationPlatform::current();
        let can_open_settings = matches!(platform, NotificationPlatform::Windows);
        NotificationPermissionStatusDto {
            platform,
            supported: true,
            authorization: NotificationAuthorization::Authorized,
            alerts_enabled: Some(true),
            sounds_enabled: Some(true),
            requested: true,
            authoritative: false,
            can_open_settings,
        }
    }

    fn request(&self) -> NotificationPermissionRequestDto {
        NotificationPermissionRequestDto {
            granted: true,
            status: self.status(),
            error: None,
        }
    }
}

#[cfg(target_os = "macos")]
pub mod macos {
    use super::*;
    use block2::RcBlock;
    use objc2_foundation::{NSBundle, NSError};
    use objc2_user_notifications::{
        UNAuthorizationOptions, UNAuthorizationStatus, UNNotificationSetting,
        UNNotificationSettings, UNUserNotificationCenter,
    };
    use std::ptr::NonNull;
    use std::sync::mpsc;
    use std::time::Duration;

    const CALLBACK_TIMEOUT: Duration = Duration::from_secs(5);

    pub fn map_authorization_status(status: UNAuthorizationStatus) -> NotificationAuthorization {
        match status {
            UNAuthorizationStatus::NotDetermined => NotificationAuthorization::NotDetermined,
            UNAuthorizationStatus::Denied => NotificationAuthorization::Denied,
            UNAuthorizationStatus::Authorized => NotificationAuthorization::Authorized,
            UNAuthorizationStatus::Provisional => NotificationAuthorization::Provisional,
            UNAuthorizationStatus::Ephemeral => NotificationAuthorization::Provisional,
            _ => NotificationAuthorization::Unknown,
        }
    }

    pub fn map_notification_setting(setting: UNNotificationSetting) -> Option<bool> {
        match setting {
            UNNotificationSetting::Enabled => Some(true),
            UNNotificationSetting::Disabled => Some(false),
            _ => None,
        }
    }

    pub fn has_bundle_identity() -> bool {
        // Only consider it a real bundled macOS app if the bundle identifier is present
        // AND the bundle path is actually inside a .app wrapper directory.
        if let Some(bundle_id) = NSBundle::mainBundle().bundleIdentifier() {
            if bundle_id.to_string().is_empty() {
                return false;
            }
            let path_str = NSBundle::mainBundle().bundlePath().to_string();
            return path_str.ends_with(".app") || path_str.contains(".app/");
        }
        false
    }

    pub fn dev_fallback_status() -> NotificationPermissionStatusDto {
        NotificationPermissionStatusDto {
            platform: NotificationPlatform::Macos,
            supported: true,
            authorization: NotificationAuthorization::Authorized,
            alerts_enabled: Some(true),
            sounds_enabled: Some(true),
            requested: true,
            authoritative: false,
            can_open_settings: true,
        }
    }

    fn read_settings(settings: &UNNotificationSettings) -> NotificationPermissionStatusDto {
        let authorization = map_authorization_status(settings.authorizationStatus());
        NotificationPermissionStatusDto {
            platform: NotificationPlatform::Macos,
            supported: true,
            authorization,
            alerts_enabled: map_notification_setting(settings.alertSetting()),
            sounds_enabled: map_notification_setting(settings.soundSetting()),
            requested: authorization != NotificationAuthorization::NotDetermined,
            authoritative: true,
            can_open_settings: true,
        }
    }

    fn query_settings() -> Option<NotificationPermissionStatusDto> {
        if !has_bundle_identity() {
            return None;
        }

        let (tx, rx) = mpsc::sync_channel::<NotificationPermissionStatusDto>(1);
        let handler = RcBlock::new(move |settings: NonNull<UNNotificationSettings>| {
            let status = read_settings(unsafe { settings.as_ref() });
            let _ = tx.try_send(status);
        });

        let dispatched = objc2::exception::catch(std::panic::AssertUnwindSafe(|| {
            let center = UNUserNotificationCenter::currentNotificationCenter();
            center.getNotificationSettingsWithCompletionHandler(&handler);
        }));

        if dispatched.is_err() {
            tracing::warn!("UNUserNotificationCenter settings query raised an exception");
            return None;
        }

        match rx.recv_timeout(CALLBACK_TIMEOUT) {
            Ok(status) => Some(status),
            Err(_) => {
                tracing::warn!("UNUserNotificationCenter settings query timed out");
                None
            }
        }
    }

    #[derive(Debug, Default, Clone, Copy)]
    pub struct MacosPermissionProvider;

    impl NotificationPermissionProvider for MacosPermissionProvider {
        fn status(&self) -> NotificationPermissionStatusDto {
            query_settings().unwrap_or_else(dev_fallback_status)
        }

        fn request(&self) -> NotificationPermissionRequestDto {
            if !has_bundle_identity() {
                // In dev mode / unbundled mode, grant immediately so dev testing works
                return NotificationPermissionRequestDto {
                    granted: true,
                    status: dev_fallback_status(),
                    error: None,
                };
            }

            let (tx, rx) = mpsc::sync_channel::<Result<bool, String>>(1);
            let handler =
                RcBlock::new(move |granted: objc2::runtime::Bool, error: *mut NSError| {
                    let outcome = if error.is_null() {
                        Ok(granted.as_bool())
                    } else {
                        Err(unsafe { (*error).localizedDescription() }.to_string())
                    };
                    let _ = tx.try_send(outcome);
                });

            let options = UNAuthorizationOptions::Alert | UNAuthorizationOptions::Sound;
            let dispatched = objc2::exception::catch(std::panic::AssertUnwindSafe(|| {
                let center = UNUserNotificationCenter::currentNotificationCenter();
                center.requestAuthorizationWithOptions_completionHandler(options, &handler);
            }));

            if dispatched.is_err() {
                return NotificationPermissionRequestDto {
                    granted: false,
                    status: dev_fallback_status(),
                    error: Some("notification authorization request failed".into()),
                };
            }

            let (granted, error) = match rx.recv_timeout(CALLBACK_TIMEOUT) {
                Ok(Ok(granted)) => (granted, None),
                Ok(Err(message)) => (false, Some(message)),
                Err(_) => (false, Some("authorization request timed out".to_string())),
            };

            let status = query_settings().unwrap_or_else(dev_fallback_status);

            NotificationPermissionRequestDto {
                granted,
                status,
                error,
            }
        }
    }
}

//! Notification dispatch orchestration.
//!
//! The service owns preflight and submission policy. Both the OS permission
//! query and the native submitter sit behind traits so command-level behavior
//! can be tested without ever displaying a real notification.

use super::model::{
    format_notification, DispatchNotificationRequest, DispatchNotificationResult,
    NotificationContent, NotificationDispatchReason, NotificationPermissionRequestDto,
    NotificationPermissionStatusDto, NotificationProbeOutcome, NotificationProbeResult,
    NotificationSource,
};
use super::permission::{platform_permission_provider, NotificationPermissionProvider};

/// Seam over the native notification backend.
///
/// Keeping submission behind a trait allows a fake backend in tests and a
/// future platform-specific silent adapter without changing the IPC contract.
pub trait NativeNotificationBackend: Send + Sync {
    fn submit(&self, content: &NotificationContent) -> Result<(), String>;
}

/// Preflight decision made before any submission is attempted.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PreflightDecision {
    Submit,
    Reject(NotificationDispatchReason),
}

/// Decide whether a dispatch may proceed for a given permission status.
///
/// Only an authoritative query can block: a non-authoritative `unknown` (every
/// current Windows/Linux build) is allowed through so those platforms keep
/// working, while macOS `denied`/`not-determined` short-circuit before the
/// backend can claim a bogus success.
pub fn preflight(status: &NotificationPermissionStatusDto) -> PreflightDecision {
    if !status.supported {
        return PreflightDecision::Reject(NotificationDispatchReason::Unsupported);
    }
    if status.is_blocked() {
        return PreflightDecision::Reject(NotificationDispatchReason::BlockedBySystem);
    }
    if status.needs_permission_request() {
        // Never prompt implicitly: the UI must ask via an explicit user action.
        return PreflightDecision::Reject(NotificationDispatchReason::PermissionRequired);
    }
    PreflightDecision::Submit
}

/// Notification domain service.
pub struct NotificationService {
    permissions: Box<dyn NotificationPermissionProvider>,
    backend: Box<dyn NativeNotificationBackend>,
}

impl NotificationService {
    pub fn new(
        permissions: Box<dyn NotificationPermissionProvider>,
        backend: Box<dyn NativeNotificationBackend>,
    ) -> Self {
        Self {
            permissions,
            backend,
        }
    }

    /// Service wired to the real platform permission provider.
    pub fn with_platform_permissions(backend: Box<dyn NativeNotificationBackend>) -> Self {
        Self::new(platform_permission_provider(), backend)
    }

    pub fn permission_status(&self) -> NotificationPermissionStatusDto {
        self.permissions.status()
    }

    /// Explicit, user-initiated authorization request.
    pub fn request_permission(&self) -> NotificationPermissionRequestDto {
        self.permissions.request()
    }

    /// Format, preflight, and submit one notification.
    pub fn dispatch(&self, request: &DispatchNotificationRequest) -> DispatchNotificationResult {
        let status = self.permissions.status();
        if let PreflightDecision::Reject(reason) = preflight(&status) {
            return DispatchNotificationResult::rejected(reason);
        }

        let content = format_notification(request);
        match self.backend.submit(&content) {
            Ok(()) => DispatchNotificationResult::submitted(),
            Err(error) => {
                tracing::warn!("native notification submission failed: {error}");
                DispatchNotificationResult::rejected(NotificationDispatchReason::BackendError)
            }
        }
    }

    /// Report readiness, optionally submitting one visible test notification.
    ///
    /// Reports `submitted`, never `visibly-delivered`: Focus and
    /// Do-Not-Disturb can suppress a banner with no signal back to rorca.
    pub fn probe_delivery(&self, send_test: bool) -> NotificationProbeResult {
        let status = self.permissions.status();

        let outcome = match preflight(&status) {
            PreflightDecision::Reject(NotificationDispatchReason::BlockedBySystem) => {
                NotificationProbeOutcome::BlockedBySystem
            }
            PreflightDecision::Reject(NotificationDispatchReason::PermissionRequired) => {
                NotificationProbeOutcome::PermissionRequired
            }
            PreflightDecision::Reject(NotificationDispatchReason::Unsupported) => {
                NotificationProbeOutcome::Unsupported
            }
            PreflightDecision::Reject(NotificationDispatchReason::BackendError) => {
                NotificationProbeOutcome::Failed
            }
            PreflightDecision::Submit => NotificationProbeOutcome::Ready,
        };

        if outcome != NotificationProbeOutcome::Ready || !send_test {
            return NotificationProbeResult {
                outcome,
                status,
                test_submitted: false,
            };
        }

        let content = format_notification(&DispatchNotificationRequest {
            source: NotificationSource::Test,
            ..Default::default()
        });

        match self.backend.submit(&content) {
            Ok(()) => NotificationProbeResult {
                outcome: NotificationProbeOutcome::Submitted,
                status,
                test_submitted: true,
            },
            Err(error) => {
                tracing::warn!("notification probe submission failed: {error}");
                NotificationProbeResult {
                    outcome: NotificationProbeOutcome::Failed,
                    status,
                    test_submitted: false,
                }
            }
        }
    }
}

impl std::fmt::Debug for NotificationService {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("NotificationService")
            .finish_non_exhaustive()
    }
}

#[cfg(test)]
pub(crate) mod test_support {
    use super::*;
    use crate::notification::model::{NotificationAuthorization, NotificationPlatform};
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::{Arc, Mutex};

    /// Permission provider returning a scripted status.
    pub struct FakePermissionProvider {
        pub status: NotificationPermissionStatusDto,
        pub request_calls: Arc<AtomicUsize>,
    }

    impl FakePermissionProvider {
        pub fn new(status: NotificationPermissionStatusDto) -> Self {
            Self {
                status,
                request_calls: Arc::new(AtomicUsize::new(0)),
            }
        }
    }

    impl NotificationPermissionProvider for FakePermissionProvider {
        fn status(&self) -> NotificationPermissionStatusDto {
            self.status.clone()
        }

        fn request(&self) -> NotificationPermissionRequestDto {
            self.request_calls.fetch_add(1, Ordering::SeqCst);
            NotificationPermissionRequestDto {
                granted: self.status.authorization == NotificationAuthorization::Authorized,
                status: self.status.clone(),
                error: None,
            }
        }
    }

    /// Backend recording submissions instead of showing notifications.
    #[derive(Default)]
    pub struct FakeBackend {
        pub submissions: Mutex<Vec<NotificationContent>>,
        pub fail_with: Option<String>,
    }

    impl FakeBackend {
        pub fn failing(message: &str) -> Self {
            Self {
                submissions: Mutex::new(Vec::new()),
                fail_with: Some(message.to_string()),
            }
        }

        pub fn count(&self) -> usize {
            self.submissions.lock().expect("submissions lock").len()
        }

        pub fn first_title(&self) -> Option<String> {
            self.submissions
                .lock()
                .expect("submissions lock")
                .first()
                .map(|content| content.title.clone())
        }

        pub fn first_body(&self) -> Option<String> {
            self.submissions
                .lock()
                .expect("submissions lock")
                .first()
                .map(|content| content.body.clone())
        }
    }

    impl NativeNotificationBackend for Arc<FakeBackend> {
        fn submit(&self, content: &NotificationContent) -> Result<(), String> {
            if let Some(error) = &self.fail_with {
                return Err(error.clone());
            }
            self.submissions
                .lock()
                .expect("submissions lock")
                .push(content.clone());
            Ok(())
        }
    }

    /// Authoritative macOS-shaped status for a given authorization value.
    pub fn macos_status(
        authorization: NotificationAuthorization,
    ) -> NotificationPermissionStatusDto {
        NotificationPermissionStatusDto {
            platform: NotificationPlatform::Macos,
            supported: true,
            authorization,
            alerts_enabled: Some(authorization == NotificationAuthorization::Authorized),
            sounds_enabled: Some(authorization == NotificationAuthorization::Authorized),
            requested: authorization != NotificationAuthorization::NotDetermined,
            authoritative: true,
            can_open_settings: true,
        }
    }

    /// Service backed entirely by fakes.
    pub fn service_with(
        status: NotificationPermissionStatusDto,
        backend: Arc<FakeBackend>,
    ) -> NotificationService {
        NotificationService::new(
            Box::new(FakePermissionProvider::new(status)),
            Box::new(backend),
        )
    }
}

#[cfg(test)]
mod tests {
    use super::test_support::*;
    use super::*;
    use crate::notification::model::{NotificationAuthorization, NotificationPlatform};
    use std::sync::atomic::Ordering;
    use std::sync::Arc;

    fn agent_request() -> DispatchNotificationRequest {
        DispatchNotificationRequest {
            source: NotificationSource::AgentTaskComplete,
            agent_label: Some("Claude".into()),
            worktree_label: Some("feat/login".into()),
            ..Default::default()
        }
    }

    #[test]
    fn authorized_status_submits_exactly_one_notification() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Authorized),
            Arc::clone(&backend),
        );

        let result = service.dispatch(&agent_request());

        assert!(result.submitted);
        assert!(result.reason.is_none());
        assert_eq!(backend.count(), 1);
        assert_eq!(backend.first_title().as_deref(), Some("Claude finished"));
        assert_eq!(backend.first_body().as_deref(), Some("feat/login"));
    }

    #[test]
    fn denied_macos_status_blocks_before_submitting() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Denied),
            Arc::clone(&backend),
        );

        let result = service.dispatch(&agent_request());

        assert!(!result.submitted);
        assert_eq!(
            result.reason,
            Some(NotificationDispatchReason::BlockedBySystem)
        );
        // Critical: the backend must never be reached when the OS denied us.
        assert_eq!(backend.count(), 0);
    }

    #[test]
    fn not_determined_returns_permission_required_without_implicit_prompt() {
        let backend = Arc::new(FakeBackend::default());
        let provider =
            FakePermissionProvider::new(macos_status(NotificationAuthorization::NotDetermined));
        let request_calls = Arc::clone(&provider.request_calls);
        let service = NotificationService::new(Box::new(provider), Box::new(Arc::clone(&backend)));

        let result = service.dispatch(&agent_request());

        assert_eq!(
            result.reason,
            Some(NotificationDispatchReason::PermissionRequired)
        );
        assert_eq!(backend.count(), 0);
        // A background event must never trigger a permission prompt.
        assert_eq!(request_calls.load(Ordering::SeqCst), 0);
    }

    #[test]
    fn backend_failure_is_reported_as_a_structured_reason() {
        let backend = Arc::new(FakeBackend::failing("dbus unavailable"));
        let service = service_with(
            macos_status(NotificationAuthorization::Authorized),
            Arc::clone(&backend),
        );

        let result = service.dispatch(&agent_request());

        assert!(!result.submitted);
        assert_eq!(
            result.reason,
            Some(NotificationDispatchReason::BackendError)
        );
    }

    #[test]
    fn provisional_authorization_is_allowed_to_dispatch() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Provisional),
            Arc::clone(&backend),
        );

        assert!(service.dispatch(&agent_request()).submitted);
        assert_eq!(backend.count(), 1);
    }

    #[test]
    fn non_authoritative_unknown_status_still_dispatches() {
        // Windows/Linux report unknown; they must keep working rather than
        // being blocked by the absence of an authoritative query.
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            NotificationPermissionStatusDto::non_authoritative(NotificationPlatform::Linux, false),
            Arc::clone(&backend),
        );

        assert!(service.dispatch(&agent_request()).submitted);
        assert_eq!(backend.count(), 1);
    }

    #[test]
    fn unsupported_platform_rejects_dispatch() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            NotificationPermissionStatusDto::unsupported(NotificationPlatform::Other),
            Arc::clone(&backend),
        );

        let result = service.dispatch(&agent_request());

        assert_eq!(result.reason, Some(NotificationDispatchReason::Unsupported));
        assert_eq!(backend.count(), 0);
    }

    #[test]
    fn dispatched_content_is_sanitized_before_reaching_the_backend() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Authorized),
            Arc::clone(&backend),
        );

        service.dispatch(&DispatchNotificationRequest {
            source: NotificationSource::TerminalBell,
            worktree_label: Some("feat/login".into()),
            terminal_title: Some("run\u{1b}[31m\ntest".into()),
            ..Default::default()
        });

        let body = backend.first_body().expect("submitted body");
        assert!(!body.contains('\n'));
        assert!(!body.contains('\u{1b}'));
    }

    #[test]
    fn probe_without_test_reports_ready_and_sends_nothing() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Authorized),
            Arc::clone(&backend),
        );

        let probe = service.probe_delivery(false);

        assert_eq!(probe.outcome, NotificationProbeOutcome::Ready);
        assert!(!probe.test_submitted);
        assert_eq!(backend.count(), 0);
    }

    #[test]
    fn probe_with_test_submits_exactly_one_test_notification() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Authorized),
            Arc::clone(&backend),
        );

        let probe = service.probe_delivery(true);

        assert_eq!(probe.outcome, NotificationProbeOutcome::Submitted);
        assert!(probe.test_submitted);
        assert_eq!(backend.count(), 1);
        assert_eq!(
            backend.first_title().as_deref(),
            Some("Ferryx notifications are working")
        );
    }

    #[test]
    fn probe_reports_blocked_without_sending_a_test() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Denied),
            Arc::clone(&backend),
        );

        let probe = service.probe_delivery(true);

        assert_eq!(probe.outcome, NotificationProbeOutcome::BlockedBySystem);
        assert!(!probe.test_submitted);
        assert_eq!(backend.count(), 0);
        // The UI needs this to offer "Open System Settings".
        assert!(probe.status.can_open_settings);
    }

    #[test]
    fn probe_reports_permission_required_without_prompting() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::NotDetermined),
            Arc::clone(&backend),
        );

        let probe = service.probe_delivery(true);

        assert_eq!(probe.outcome, NotificationProbeOutcome::PermissionRequired);
        assert!(!probe.test_submitted);
        assert_eq!(backend.count(), 0);
    }

    #[test]
    fn probe_failure_reports_failed_not_submitted() {
        let backend = Arc::new(FakeBackend::failing("backend down"));
        let service = service_with(
            macos_status(NotificationAuthorization::Authorized),
            Arc::clone(&backend),
        );

        let probe = service.probe_delivery(true);

        assert_eq!(probe.outcome, NotificationProbeOutcome::Failed);
        assert!(!probe.test_submitted);
    }

    #[test]
    fn preflight_decisions_cover_every_authorization_state() {
        assert_eq!(
            preflight(&macos_status(NotificationAuthorization::Authorized)),
            PreflightDecision::Submit
        );
        assert_eq!(
            preflight(&macos_status(NotificationAuthorization::Provisional)),
            PreflightDecision::Submit
        );
        assert_eq!(
            preflight(&macos_status(NotificationAuthorization::Denied)),
            PreflightDecision::Reject(NotificationDispatchReason::BlockedBySystem)
        );
        assert_eq!(
            preflight(&macos_status(NotificationAuthorization::NotDetermined)),
            PreflightDecision::Reject(NotificationDispatchReason::PermissionRequired)
        );
        assert_eq!(
            preflight(&macos_status(NotificationAuthorization::Unknown)),
            PreflightDecision::Submit
        );
    }

    #[test]
    fn non_authoritative_denied_does_not_block() {
        // A denied value without an authoritative query is a guess and must
        // not silently suppress notifications.
        let mut status = macos_status(NotificationAuthorization::Denied);
        status.authoritative = false;

        assert_eq!(preflight(&status), PreflightDecision::Submit);
    }

    #[test]
    fn explicit_permission_request_reaches_the_provider_once() {
        let provider =
            FakePermissionProvider::new(macos_status(NotificationAuthorization::Authorized));
        let request_calls = Arc::clone(&provider.request_calls);
        let service = NotificationService::new(
            Box::new(provider),
            Box::new(Arc::new(FakeBackend::default())),
        );

        let result = service.request_permission();

        assert!(result.granted);
        assert_eq!(request_calls.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn permission_status_passes_through_the_provider_value() {
        let service = service_with(
            macos_status(NotificationAuthorization::Denied),
            Arc::new(FakeBackend::default()),
        );

        let status = service.permission_status();

        assert_eq!(status.authorization, NotificationAuthorization::Denied);
        assert!(status.is_blocked());
    }
}

//! Custom notification sound playback.
//!
//! Playing the user's sound in Rust rather than the WebView keeps the selected
//! path off the JavaScript side entirely: no `asset:` protocol, no
//! `convertFileSrc(...)` scope, and no CSP expansion for local media. It also
//! makes preview and real notification playback share one code path with one
//! volume normalization point.

use super::model::{
    audio_display_name, normalize_volume, validate_audio_path, PickedAudioFile, PlaySoundReason,
    PlaySoundResult,
};
use parking_lot::Mutex;
use rodio::{Decoder, DeviceSinkBuilder, MixerDeviceSink, Player};
use std::fs::File;
use std::io::BufReader;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

/// Automatic sounds fired closer together than this collapse into one.
///
/// An agent completion and an adjacent terminal bell should not stack into a
/// double alert. Settings preview bypasses this with `force`.
pub const DEDUPE_WINDOW: Duration = Duration::from_millis(400);

/// Lazily-initialized audio output plus playback state.
///
/// The output stream is kept alive for the process lifetime; dropping it after
/// starting playback would cut the sound off immediately. Initialization is
/// deferred so a machine with no audio output device can still launch rorca.
pub struct NotificationAudioPlayer {
    output: Mutex<OutputState>,
    last_played_at: Mutex<Option<Instant>>,
}

enum OutputState {
    /// No attempt made yet.
    Uninitialized,
    Ready(MixerDeviceSink),
    /// A previous attempt failed; do not retry on every notification.
    Unavailable,
}

impl Default for NotificationAudioPlayer {
    fn default() -> Self {
        Self::new()
    }
}

impl NotificationAudioPlayer {
    pub fn new() -> Self {
        Self {
            output: Mutex::new(OutputState::Uninitialized),
            last_played_at: Mutex::new(None),
        }
    }

    /// Decode and play `path` at `volume_percent` (`0..=100`).
    ///
    /// Never panics on a moved or deleted file: every failure is reported as a
    /// structured [`PlaySoundResult`].
    pub fn play(&self, path: &Path, volume_percent: f32, force: bool) -> PlaySoundResult {
        if !force && self.is_deduped() {
            return PlaySoundResult::failed(PlaySoundReason::Deduped);
        }

        let canonical = match validate_audio_path(path) {
            Ok(canonical) => canonical,
            Err(reason) => {
                // Log the failure kind, never the full user path.
                tracing::debug!("notification sound rejected: {:?}", reason);
                return PlaySoundResult::failed(reason);
            }
        };

        let volume = normalize_volume(volume_percent);
        if volume <= 0.0 {
            // Muted: treat as a successful no-op rather than a device error.
            self.mark_played();
            return PlaySoundResult::played();
        }

        let file = match File::open(&canonical) {
            Ok(file) => file,
            Err(_) => return PlaySoundResult::failed(PlaySoundReason::NotFound),
        };

        let decoder = match Decoder::new(BufReader::new(file)) {
            Ok(decoder) => decoder,
            Err(error) => {
                tracing::debug!("notification sound decode failed: {error}");
                return PlaySoundResult::failed(PlaySoundReason::DecodeFailed);
            }
        };

        let mut output = self.output.lock();
        if matches!(*output, OutputState::Uninitialized) {
            *output = match DeviceSinkBuilder::open_default_sink() {
                Ok(mut sink) => {
                    // Silence rodio's stderr message when the process exits.
                    sink.log_on_drop(false);
                    OutputState::Ready(sink)
                }
                Err(error) => {
                    tracing::warn!("no audio output device for notification sound: {error}");
                    OutputState::Unavailable
                }
            };
        }

        let sink = match &*output {
            OutputState::Ready(sink) => sink,
            OutputState::Unavailable => {
                return PlaySoundResult::failed(PlaySoundReason::NoOutputDevice)
            }
            OutputState::Uninitialized => {
                return PlaySoundResult::failed(PlaySoundReason::BackendError)
            }
        };

        let player = Player::connect_new(sink.mixer());
        player.set_volume(volume);
        player.append(decoder);
        // Detach so playback continues after this call returns; the mixer owned
        // by the managed output stream keeps rendering it.
        player.detach();
        drop(output);

        self.mark_played();
        PlaySoundResult::played()
    }

    fn is_deduped(&self) -> bool {
        self.last_played_at
            .lock()
            .map(|last| last.elapsed() < DEDUPE_WINDOW)
            .unwrap_or(false)
    }

    fn mark_played(&self) {
        *self.last_played_at.lock() = Some(Instant::now());
    }

    /// Test-only hook to age the dedupe window.
    #[cfg(test)]
    fn set_last_played(&self, at: Option<Instant>) {
        *self.last_played_at.lock() = at;
    }
}

impl std::fmt::Debug for NotificationAudioPlayer {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("NotificationAudioPlayer")
            .finish_non_exhaustive()
    }
}

/// Build a picker result from a chosen path.
pub fn picked_audio_file(path: PathBuf) -> PickedAudioFile {
    let display_name = audio_display_name(&path);
    PickedAudioFile { path, display_name }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write;
    use tempfile::TempDir;

    fn write_file(dir: &TempDir, name: &str, bytes: &[u8]) -> PathBuf {
        let path = dir.path().join(name);
        let mut file = File::create(&path).expect("create fixture");
        file.write_all(bytes).expect("write fixture");
        path
    }

    /// Minimal valid 16-bit PCM WAV: one sample of silence.
    fn tiny_wav_bytes() -> Vec<u8> {
        let sample_rate: u32 = 44_100;
        let data: [u8; 2] = [0, 0];
        let mut wav = Vec::new();
        wav.extend_from_slice(b"RIFF");
        wav.extend_from_slice(&(36u32 + data.len() as u32).to_le_bytes());
        wav.extend_from_slice(b"WAVE");
        wav.extend_from_slice(b"fmt ");
        wav.extend_from_slice(&16u32.to_le_bytes()); // PCM chunk size
        wav.extend_from_slice(&1u16.to_le_bytes()); // PCM format
        wav.extend_from_slice(&1u16.to_le_bytes()); // mono
        wav.extend_from_slice(&sample_rate.to_le_bytes());
        wav.extend_from_slice(&(sample_rate * 2).to_le_bytes()); // byte rate
        wav.extend_from_slice(&2u16.to_le_bytes()); // block align
        wav.extend_from_slice(&16u16.to_le_bytes()); // bits per sample
        wav.extend_from_slice(b"data");
        wav.extend_from_slice(&(data.len() as u32).to_le_bytes());
        wav.extend_from_slice(&data);
        wav
    }

    #[test]
    fn missing_file_reports_not_found_without_panicking() {
        let player = NotificationAudioPlayer::new();
        let result = player.play(Path::new("/nonexistent/orca-sound.wav"), 50.0, true);

        assert!(!result.played);
        assert_eq!(result.reason, Some(PlaySoundReason::NotFound));
    }

    #[test]
    fn unsupported_extension_is_rejected_before_decoding() {
        let dir = TempDir::new().expect("tempdir");
        let path = write_file(&dir, "notes.txt", b"not audio");

        let player = NotificationAudioPlayer::new();
        let result = player.play(&path, 50.0, true);

        assert_eq!(result.reason, Some(PlaySoundReason::UnsupportedFormat));
    }

    #[test]
    fn corrupt_audio_reports_decode_failure_not_a_crash() {
        let dir = TempDir::new().expect("tempdir");
        // Valid extension, garbage contents.
        let path = write_file(&dir, "broken.wav", b"definitely not a wav file");

        let player = NotificationAudioPlayer::new();
        let result = player.play(&path, 50.0, true);

        assert!(!result.played);
        assert_eq!(result.reason, Some(PlaySoundReason::DecodeFailed));
    }

    #[test]
    fn zero_volume_short_circuits_before_touching_the_audio_device() {
        let dir = TempDir::new().expect("tempdir");
        let path = write_file(&dir, "sound.wav", &tiny_wav_bytes());

        let player = NotificationAudioPlayer::new();
        let result = player.play(&path, 0.0, true);

        // Muted playback must succeed on machines with no audio device,
        // which is the normal case in CI.
        assert!(result.played);
        assert!(result.reason.is_none());
        assert!(matches!(*player.output.lock(), OutputState::Uninitialized));
    }

    #[test]
    fn negative_and_oversized_volumes_clamp_into_range() {
        let dir = TempDir::new().expect("tempdir");
        let path = write_file(&dir, "sound.wav", &tiny_wav_bytes());
        let player = NotificationAudioPlayer::new();

        // Negative clamps to 0 -> muted no-op, never a device error.
        assert!(player.play(&path, -30.0, true).played);
    }

    #[test]
    fn rapid_automatic_sounds_are_deduped_but_force_still_plays() {
        let dir = TempDir::new().expect("tempdir");
        let path = write_file(&dir, "sound.wav", &tiny_wav_bytes());
        let player = NotificationAudioPlayer::new();

        // Simulate a sound that just played, without sleeping.
        player.set_last_played(Some(Instant::now()));

        let automatic = player.play(&path, 0.0, false);
        assert!(!automatic.played);
        assert_eq!(automatic.reason, Some(PlaySoundReason::Deduped));

        // Settings preview bypasses the dedupe window.
        let forced = player.play(&path, 0.0, true);
        assert!(forced.played);
    }

    #[test]
    fn sound_outside_the_dedupe_window_plays_again() {
        let dir = TempDir::new().expect("tempdir");
        let path = write_file(&dir, "sound.wav", &tiny_wav_bytes());
        let player = NotificationAudioPlayer::new();

        let stale = Instant::now()
            .checked_sub(DEDUPE_WINDOW * 2)
            .expect("stale instant");
        player.set_last_played(Some(stale));

        assert!(player.play(&path, 0.0, false).played);
    }

    #[test]
    fn picked_file_exposes_only_path_and_display_name() {
        let picked = picked_audio_file(PathBuf::from("/Users/someone/Music/ding.wav"));

        assert_eq!(picked.display_name, "ding.wav");
        assert_eq!(picked.path, PathBuf::from("/Users/someone/Music/ding.wav"));
    }
}

