pub async fn cmd_worktree_delete_destructive<R: Runtime>(
    app: AppHandle<R>,
    registry: State<'_, WorkspaceRegistry>,
    request: DeleteWorktreeRequest,
) -> Result<(), IpcError> {
    delete_worktree(app, registry, request, true).await
}

#[tauri::command]
pub async fn cmd_worktree_delete_preview(
    registry: State<'_, WorkspaceRegistry>,
    request: WorktreeStatusRequest,
) -> Result<BranchDeletionPreview, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || {
        let (manager, worktree) = registry
            .resolve_worktree(&request.workspace_id, &request.worktree)
            .map_err(IpcError::from)?;
        manager
            .branch_deletion_preview(&worktree.path)
            .map_err(IpcError::from)
    })
    .await
}

#[tauri::command]
pub async fn cmd_worktree_status<R: Runtime>(
    app: AppHandle<R>,
    registry: State<'_, WorkspaceRegistry>,
    request: WorktreeStatusRequest,
) -> Result<DirtyState, IpcError> {
    let registry = (*registry).clone();
    let workspace_id = request.workspace_id.clone();
    let identity = request.worktree.clone();
    let event_workspace_id = workspace_id.clone();
    let event_identity = identity.clone();

    let (status, changed) = run_blocking(move || {
        let (manager, worktree) = registry
            .resolve_worktree(&workspace_id, &identity)
            .map_err(IpcError::from)?;
        manager
            .observe_dirty_state(&worktree.path)
            .map_err(IpcError::from)
    })
    .await?;

    if changed {
        emit_worktree_changed(
            &app,
            event_workspace_id,
            event_identity,
            WorktreeChangeKind::DirtyChanged,
        )?;
    }
    Ok(status)
}

use crate::ipc::{run_blocking, IpcError};
use crate::worktree::{run_git, WorkspaceRegistry, WorktreeError, WorktreeManager};
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use tauri::State;

/// Workspace ID that shipped as a hard-coded alias for the startup repository.
/// It is no longer registered. Clients that persisted it migrate by calling
/// [`cmd_project_initial`] on startup and adopting the canonical ID it returns.
pub const LEGACY_DEFAULT_WORKSPACE_ID: &str = "default";

/// Fallback ID for a root whose folder name carries no usable characters.
const FALLBACK_WORKSPACE_ID: &str = "project";

/// Derives the canonical workspace ID for a repository root from its folder
/// name, restricted to characters `WorkspaceRegistry::validate_workspace_id`
/// accepts (no separators, whitespace, control characters, or leading `-`).
pub fn derive_workspace_id(repo_root: &Path) -> String {
    repo_root
        .file_name()
        .and_then(|name| name.to_str())
        .map(|name| {
            let slug: String = name
                .chars()
                .map(|ch| {
                    if ch.is_alphanumeric() || ch == '_' || ch == '-' {
                        ch
                    } else {
                        '-'
                    }
                })
                .collect();
            let trimmed = slug.trim_matches('-');
            if trimmed.is_empty() {
                FALLBACK_WORKSPACE_ID.to_string()
            } else {
                trimmed.to_string()
            }
        })
        .unwrap_or_else(|| FALLBACK_WORKSPACE_ID.to_string())
}

/// Registers (idempotently) and returns the single canonical project for the
/// startup repository.
///
/// The ID is derived from the repository root reported by Git, not from the
/// process working directory, so launching from a subdirectory (`src-tauri/`,
/// a worktree checkout, a test harness) still yields one stable project ID.
pub fn initial_project(registry: &WorkspaceRegistry) -> Result<RegisteredProject, IpcError> {
    let cwd = std::env::current_dir().map_err(|error| {
        IpcError::from(WorktreeError::InvalidPath {
            path: PathBuf::from("."),
            reason: format!("the startup working directory is unavailable: {error}"),
        })
    })?;
    register_canonical_project(registry, &cwd, None)
}

/// Registers a repository root under exactly one workspace ID.
///
/// Canonical-root uniqueness: a root already registered under some ID resolves
/// to that existing project instead of gaining a second alias, so the registry
/// holds at most one ID per repository root. When `preferred_id` is `None` the
/// ID is derived from the root's folder name.
fn register_canonical_project(
    registry: &WorkspaceRegistry,
    repo_path: &Path,
    preferred_id: Option<&str>,
) -> Result<RegisteredProject, IpcError> {
    // `try_new` walks up to the Git top level, canonicalizes it, and rejects
    // non-Git paths, so the uniqueness check below compares canonical roots.
    let repo_root = WorktreeManager::try_new(repo_path)
        .map_err(IpcError::from)?
        .repo_root()
        .to_path_buf();

    if let Some((workspace_id, _)) = registry
        .list()
        .into_iter()
        .find(|(_, manager)| manager.repo_root() == repo_root)
    {
        return Ok(RegisteredProject {
            workspace_id,
            repo_root,
        });
    }

    let workspace_id = match preferred_id {
        Some(requested) => requested.to_string(),
        None => derive_workspace_id(&repo_root),
    };
    registry
        .register(&workspace_id, &repo_root)
        .map_err(IpcError::from)?;
    let repo_root = registry.repo_root(&workspace_id).map_err(IpcError::from)?;
    Ok(RegisteredProject {
        workspace_id,
        repo_root,
    })
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct RegisterProjectRequest {
    pub workspace_id: String,
    pub repo_path: PathBuf,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RegisteredProject {
    pub workspace_id: String,
    pub repo_root: PathBuf,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ProjectBranchesRequest {
    pub workspace_id: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LocalBranch {
    pub name: String,
    pub is_current: bool,
}

/// Registers a project, enforcing one workspace ID per canonical repository
/// root. Requesting a new ID for an already-registered root is not an error:
/// the existing project is returned, so a client holding a stale ID (such as
/// the legacy `default`) migrates onto the canonical one instead of creating a
/// duplicate alias. Callers must adopt the returned `workspaceId`.
#[tauri::command]
pub async fn cmd_project_register(
    registry: State<'_, WorkspaceRegistry>,
    request: RegisterProjectRequest,
) -> Result<RegisteredProject, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || {
        register_canonical_project(
            &registry,
            &request.repo_path,
            Some(request.workspace_id.as_str()),
        )
    })
    .await
}

/// Returns the one canonical project for the repository the app was started
/// from, registering it on first call. Replaces the previous startup behaviour
/// of registering both a derived ID and a `default` alias for the same root.
#[tauri::command]
pub async fn cmd_project_initial(
    registry: State<'_, WorkspaceRegistry>,
) -> Result<RegisteredProject, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || initial_project(&registry)).await
}

#[tauri::command]
pub async fn cmd_project_branches(
    registry: State<'_, WorkspaceRegistry>,
    request: ProjectBranchesRequest,
) -> Result<Vec<LocalBranch>, IpcError> {
    let registry = (*registry).clone();
    run_blocking(move || {
        let manager = registry
            .manager(&request.workspace_id)
            .map_err(IpcError::from)?;
        let branch_output = run_git(
            manager.repo_root(),
            &[
                "for-each-ref",
                "--sort=refname",
                "--format=%(refname:short)",
                "refs/heads/",
            ],
        )
        .map_err(IpcError::from)?;
        let current_output =
            run_git(manager.repo_root(), &["branch", "--show-current"]).map_err(IpcError::from)?;
        let current = current_output.trim();

        let mut branches = branch_output
            .lines()
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .map(|name| LocalBranch {
                name: name.to_string(),
                is_current: !current.is_empty() && name == current,
            })
            .collect::<Vec<_>>();
        branches.sort_by(|left, right| left.name.cmp(&right.name));
        Ok(branches)
    })
    .await
}

use crate::browser::BrowserError;
use serde::Deserialize;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ImportedCookie {
    pub name: String,
    pub value: String,
    pub domain: Option<String>,
    pub path: String,
    pub secure: bool,
    pub http_only: bool,
    pub expires_unix: Option<i64>,
    pub same_site: Option<String>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct JsonCookie {
    name: String,
    #[serde(default)]
    value: String,
    #[serde(default, alias = "host")]
    domain: Option<String>,
    #[serde(default)]
    path: Option<String>,
    #[serde(default)]
    secure: bool,
    #[serde(default, alias = "http_only")]
    http_only: bool,
    #[serde(default, alias = "expirationDate", alias = "expiration_date", alias = "expires")]
    expiration_date: Option<f64>,
    #[serde(default, alias = "same_site")]
    same_site: Option<String>,
}

fn from_json_cookie(cookie: JsonCookie) -> Result<ImportedCookie, BrowserError> {
    let name = cookie.name.trim().to_string();
    if name.is_empty() {
        return Err(BrowserError::CookieImport("cookie name cannot be empty".into()));
    }
    Ok(ImportedCookie {
        name,
        value: cookie.value,
        domain: cookie.domain.map(|value| value.trim().to_string()).filter(|value| !value.is_empty()),
        path: cookie.path.filter(|value| value.starts_with('/')).unwrap_or_else(|| "/".into()),
        secure: cookie.secure,
        http_only: cookie.http_only,
        expires_unix: cookie.expiration_date.and_then(|value| {
            if value.is_finite() && value > 0.0 { Some(value.floor() as i64) } else { None }
        }),
        same_site: cookie.same_site.map(|value| value.to_ascii_lowercase()),
    })
}

fn parse_json(input: &str) -> Result<Vec<ImportedCookie>, BrowserError> {
    let value: serde_json::Value = serde_json::from_str(input)
        .map_err(|error| BrowserError::CookieImport(format!("invalid JSON cookie file: {error}")))?;
    let cookie_values = match value {
        serde_json::Value::Array(values) => values,
        serde_json::Value::Object(mut object) => object
            .remove("cookies")
            .and_then(|value| value.as_array().cloned())
            .ok_or_else(|| BrowserError::CookieImport("JSON must be an array or contain a cookies array".into()))?,
        _ => return Err(BrowserError::CookieImport("JSON cookie file must contain an array".into())),
    };
    cookie_values
        .into_iter()
        .map(|value| {
            serde_json::from_value::<JsonCookie>(value)
                .map_err(|error| BrowserError::CookieImport(format!("invalid cookie entry: {error}")))
                .and_then(from_json_cookie)
        })
        .collect()
}

fn parse_netscape(input: &str) -> Result<Vec<ImportedCookie>, BrowserError> {
    let mut cookies = Vec::new();
    for (line_number, raw_line) in input.lines().enumerate() {
        let mut line = raw_line.trim();
        if line.is_empty() || (line.starts_with('#') && !line.starts_with("#HttpOnly_")) {
            continue;
        }
        let mut http_only = false;
        if let Some(rest) = line.strip_prefix("#HttpOnly_") {
            http_only = true;
            line = rest;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        if fields.len() < 7 {
            return Err(BrowserError::CookieImport(format!(
                "invalid Netscape cookie line {}: expected 7 tab-separated fields",
                line_number + 1
            )));
        }
        let name = fields[5].trim();
        if name.is_empty() {
            return Err(BrowserError::CookieImport(format!("empty cookie name on line {}", line_number + 1)));
        }
        let expires_unix = fields[4].trim().parse::<i64>().ok().filter(|value| *value > 0);
        cookies.push(ImportedCookie {
            name: name.to_string(),
            value: fields[6].to_string(),
            domain: Some(fields[0].trim().to_string()).filter(|value| !value.is_empty()),
            path: if fields[2].starts_with('/') { fields[2].to_string() } else { "/".into() },
            secure: fields[3].eq_ignore_ascii_case("TRUE"),
            http_only,
            expires_unix,
            same_site: None,
        });
    }
    Ok(cookies)
}

pub fn parse_cookie_file(input: &str) -> Result<Vec<ImportedCookie>, BrowserError> {
    let trimmed = input.trim_start();
    let cookies = if trimmed.starts_with('[') || trimmed.starts_with('{') {
        parse_json(input)?
    } else {
        parse_netscape(input)?
    };
    if cookies.is_empty() {
        return Err(BrowserError::CookieImport("cookie file did not contain any cookies".into()));
    }
    Ok(cookies)
}

